"""Give every autogenerated foreign key in a migration an explicit name.

Alembic's autogenerate emits ``create_foreign_key(None, ...)``. SQLite batch mode refuses an unnamed
constraint ("Constraint must have a name"), and an unnamed constraint cannot be dropped again on
PostgreSQL either. This rewrites the file in place, naming each one ``fk_<table>_<column>`` and filling
in the matching ``drop_constraint(None, type_='foreignkey')`` calls in the downgrade.

    .venv/Scripts/python.exe build/name_migration_fks.py migrations/versions/<file>.py
"""
from __future__ import annotations

import io
import re
import sys
from collections import defaultdict

BATCH = re.compile(r"op\.batch_alter_table\(\s*'([^']+)'")
CREATE = re.compile(r"(batch_op\.create_foreign_key\()None(,\s*'[^']+',\s*\[')([^']+)('\])")
DROP = re.compile(r"batch_op\.drop_constraint\(None, type_='foreignkey'\)")


def main(path: str) -> int:
    lines = io.open(path, encoding="utf-8").read().splitlines()
    created: dict[str, list[str]] = defaultdict(list)
    table = ""
    out: list[str] = []
    named = 0

    for line in lines:  # pass 1: name the creates, remembering them per table
        m = BATCH.search(line)
        if m:
            table = m.group(1)
        c = CREATE.search(line)
        if c:
            name = f"fk_{table}_{c.group(3)}"
            created[table].append(name)
            line = CREATE.sub(lambda mm: f"{mm.group(1)}'{name}'{mm.group(2)}{mm.group(3)}{mm.group(4)}", line, count=1)
            named += 1
        out.append(line)

    pending = {t: list(reversed(names)) for t, names in created.items()}  # downgrade drops in reverse
    table = ""
    final: list[str] = []
    dropped = 0
    for line in out:  # pass 2: fill in the drops
        m = BATCH.search(line)
        if m:
            table = m.group(1)
        if DROP.search(line) and pending.get(table):
            name = pending[table].pop(0)
            line = DROP.sub(f"batch_op.drop_constraint('{name}', type_='foreignkey')", line, count=1)
            dropped += 1
        final.append(line)

    io.open(path, "w", encoding="utf-8", newline="\n").write("\n".join(final) + "\n")
    leftover = {t: n for t, n in pending.items() if n}
    print(f"named {named} foreign keys, filled {dropped} drop_constraint calls")
    if leftover:
        print("WARNING: unmatched drops for", leftover)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1]))
